```ts
// One transaction at a time on this connection: BEGIN inside an open
// transaction throws, so callers that await inside their callback (a sell
// burst, a shard flush) must queue instead of interleaving (TASK-67).
let txTail: Promise<unknown> = Promise.resolve();
...
async withTransaction<T>(fn) {
  const prev = txTail;
  let release!: () => void;
  txTail = new Promise((r) => (release = r));
  await prev.catch(() => {});
  try {
    await d.run(sql`BEGIN`);
    ...
  } finally { release(); }
}
```

